// Keep only genuine fare drops. The Actor returns BASELINE rows on a
// watch's first check, one SUMMARY row per check, and ERROR rows for
// routes that failed — none of those are alerts. Itinerary rows
// whose changeType is PRICE_DROP or TARGET_HIT are. Drops already in the Alert Log are skipped, as
// are duplicates inside this batch. When nothing qualifies, emit ONE
// marker item so the loop still advances to the next watch.
const settings = $('Set your watch settings').first().json;
const cap = Number(settings.max_alerts_per_watch) || 10;
const logged = new Set();
for (const item of $('Read alert log').all()) {
  const j = item.json;
  if (j.flightKey) logged.add(`${j.flightKey}|${j.newPrice}`);
}
const seen = new Set();
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  if (j.changeType !== 'PRICE_DROP' && j.changeType !== 'TARGET_HIT') continue;
  const key = `${j.flightKey}|${j.price}`;
  if (logged.has(key) || seen.has(key)) continue;
  seen.add(key);
  out.push({ json: { ...j, isDrop: 1 } });
  if (out.length >= cap) break;
}
return out.length ? out : [{ json: { isDrop: 0 } }];

// Build the Slack alert text and the Alert Log row for one drop.
// Log fields are named exactly like the Alert Log tab's headers.
const j = $json;
const route = `${j.origin} \u2192 ${j.destination}`;
const when = j.returnDate ? `${j.departureDate} \u2192 ${j.returnDate}` : `${j.departureDate}`;
const airlines = (j.airlines || []).join(', ');
const kind = j.changeType === 'TARGET_HIT' ? '\u{1F3AF} Target hit' : '\u2708\uFE0F Fare drop';
const times = j.departAt ? `\n${j.departAt} \u2192 ${j.arriveAt || ''}` : '';
const drop = j.previousPrice != null
  ? `was $${j.previousPrice}, now $${j.price} (-${j.dropPercent}%)`
  : `now $${j.price}`;
const alertText = `${kind}: ${route} \u00B7 ${when}\n${airlines}${times}\n${drop}\n${j.googleFlightsUrl || ''}`.trim();
return { json: {
  alertText,
  flightKey: j.flightKey,
  route,
  departureDate: j.departureDate,
  airlines,
  previousPrice: j.previousPrice ?? '',
  newPrice: j.price,
  dropPercent: j.dropPercent ?? '',
  changeType: j.changeType,
  alertedAt: new Date().toISOString(),
  link: j.googleFlightsUrl || '',
} };
